#!/usr/bin/env node
/*
 * Emit public/flora.js — the panel flora as a standalone, cacheable script.
 *
 *   node scripts/build-flora-bundle.mjs            # write it
 *   node scripts/build-flora-bundle.mjs --check    # CI: fail if it is stale
 *
 * The module lives inside index.html's inline script, which is fine for the
 * homepage and useless for anything else. The resume page wants it too, and
 * the resume is the page search sends people to: inlining 40KB of growth
 * algorithm into an 11KB document would make the decoration more than three
 * times the weight of the thing it decorates. As a separate deferred file it
 * costs the HTML nothing, arrives after paint, and is cached across visits.
 *
 * Extracted between the flora:begin / flora:end markers, the same source
 * scripts/measure-flora.mjs and scripts/build-vine-lab.mjs read — so there is
 * still exactly one copy of the algorithm. --check re-extracts and compares,
 * so the committed bundle cannot drift from index.html without CI noticing.
 *
 * No eval: the module is wrapped in an ordinary function whose parameters
 * shadow the globals it expects, so a page with a strict CSP can still run it.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SRC = path.join(ROOT, 'index.html');
const OUT = path.join(ROOT, 'public', 'flora.js');

function extract() {
  const src = fs.readFileSync(SRC, 'utf8');
  const b = src.indexOf('/* flora:begin');
  const e = src.indexOf('/* flora:end */', b);
  if (b < 0 || e < 0) throw new Error('flora:begin / flora:end markers not found in index.html');
  return src.slice(src.indexOf('const panelFlora', b), e).trimEnd();
}

function bundle(module) {
  return `/* GENERATED by scripts/build-flora-bundle.mjs — do not edit.
 *
 * The panel flora, lifted out of index.html between its flora:begin and
 * flora:end markers. One copy of the algorithm, three consumers: the homepage
 * (inline), the comparison lab, and this.
 *
 * Usage:
 *   const vine = createFlora(canvasElement, '?vine=creep');
 *   vine.plant('left');
 *   // then call vine.tick(msSinceLastTick) from your own loop
 */
(function () {
  'use strict';

  // The module reads these from its enclosing scope in index.html. Here they
  // are parameters, which is why this needs no eval.
  function makeFlora(document, window, location, URLSearchParams, dprCap, prefersReducedMotion) {
${module.split('\n').map((l) => (l.trim() ? '    ' + l : l)).join('\n')}
    return panelFlora;
  }

  window.createFlora = function createFlora(canvas, search) {
    if (!canvas) throw new Error('createFlora needs a canvas element');
    return makeFlora(
      { getElementById: function () { return canvas; } },
      window,
      { search: search || '' },
      URLSearchParams,
      1.5,
      typeof window.matchMedia === 'function'
        ? window.matchMedia('(prefers-reduced-motion: reduce)')
        : null,
    );
  };

  /**
   * Drive any number of flora instances from one 30fps loop, matching the cap
   * the homepage runs its panels at. Returns a stop function.
   */
  window.runFlora = function runFlora(instances) {
    var FRAME_MS = 1000 / 30;
    var last = 0;
    var raf = 0;
    var stopped = false;
    function frame(t) {
      if (stopped) return;
      raf = requestAnimationFrame(frame);
      if (last && t - last < FRAME_MS - 2) return;
      var dt = last ? Math.min(t - last, 100) : FRAME_MS;
      last = t;
      for (var i = 0; i < instances.length; i += 1) instances[i].tick(dt);
    }
    raf = requestAnimationFrame(frame);
    return function stop() { stopped = true; cancelAnimationFrame(raf); };
  };
})();
`;
}

const module = extract();
const expected = bundle(module);

if (process.argv.includes('--check')) {
  if (!fs.existsSync(OUT)) {
    console.error('public/flora.js is missing — run node scripts/build-flora-bundle.mjs');
    process.exit(1);
  }
  const actual = fs.readFileSync(OUT, 'utf8');
  if (actual !== expected) {
    console.error('public/flora.js is STALE — index.html has changed since it was generated.');
    console.error('Run: node scripts/build-flora-bundle.mjs');
    process.exit(1);
  }
  console.log(`flora bundle OK — ${(actual.length / 1024).toFixed(1)}KB, in step with index.html`);
  process.exit(0);
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, expected);
console.log(`wrote public/flora.js — ${(expected.length / 1024).toFixed(1)}KB (module ${(module.length / 1024).toFixed(1)}KB)`);
